  const prepared = rows.map(([ar, forms]) => ({ ar, forms }));
  const wordPattern = /[A-Za-z0-9\u0621-\u063A\u0641-\u064A\u066E-\u06D3\u06FA-\u06FC\u064B-\u065F\u0670]+(?:['’][A-Za-z0-9\u0621-\u063A\u0641-\u064A\u066E-\u06D3\u06FA-\u06FC\u064B-\u065F\u0670]+)*/g;

  function buildSourceMap(sourceCode) {
    const map = new Map();
    prepared.forEach(entry => {
      const aliases = [entry.ar];
      if (sourceCode === "auto" || sourceCode === "ar") {
        Object.keys(entry.forms).forEach(code => aliases.push(...values(entry.forms[code])));
      } else {
        aliases.push(...values(entry.forms[sourceCode]));
      }
      aliases.forEach(alias => {
        const key = normalize(alias);
        if (key && !map.has(key)) map.set(key, entry);
      });
    });
    return map;
  }

  function replaceWithMap(text, map, targetCode) {
    const words = [];
    wordPattern.lastIndex = 0;
    let match;
    while ((match = wordPattern.exec(text))) {
      words.push({ value: match[0], start: match.index, end: match.index + match[0].length });
    }
    let output = "", cursor = 0, matchedWords = 0, i = 0;
    const unresolved = [];
    while (i < words.length) {
      let found = null, foundEnd = i;
      const max = Math.min(6, words.length - i);
      for (let size = max; size >= 1; size--) {
        const endIndex = i + size - 1;
        let separated = true;
        for (let k = i; k < endIndex; k++) {
          if (!/^\s+$/.test(text.slice(words[k].end, words[k + 1].start))) { separated = false; break; }
        }
        if (!separated) continue;
        const key = words.slice(i, i + size).map(item => normalize(item.value)).join(" ");
        if (map.has(key)) { found = map.get(key); foundEnd = endIndex; break; }
      }
      if (found) {
        const form = targetCode === "ar" ? found.ar : values(found.forms[targetCode])[0] || found.ar;
        output += text.slice(cursor, words[i].start) + form;
        cursor = words[foundEnd].end;
        matchedWords += foundEnd - i + 1;
        i = foundEnd + 1;
      } else {
        const token = words[i].value;
        if (token.length > 1 && !/^\d+$/.test(token)) unresolved.push(token);
        i++;
      }
    }
    output += text.slice(cursor);
    return { translation: output, matchedWords, totalWords: words.length, unresolved: [...new Set(unresolved)].slice(0, 12) };
  }

  function translate(text, sourceCode, targetCode) {
    const original = String(text || "");
    if (!original.trim()) return { translation: "", corrections: [], meta: { offline: true } };
    if (sourceCode === targetCode) return { translation: original, corrections: [], meta: { offline: true, matchedWords: 0, totalWords: 0, sameDialect: true } };

    let input = original;
    if (/[A-Za-z]/.test(input) && window.SEIF_ARABIZI && window.SEIF_ARABIZI.isLikely(input)) {
      input = window.SEIF_ARABIZI.toArabic(input);
    }
    const sourceMap = buildSourceMap(sourceCode || "auto");
    const result = replaceWithMap(input, sourceMap, targetCode || "ar");
    const percent = result.totalWords ? Math.round(result.matchedWords / result.totalWords * 100) : 100;
    const missingNote = result.unresolved.length ? " · بقيت كما هي: " + result.unresolved.slice(0, 5).join("، ") : "";
    const status = "قاموس محلي دون إنترنت · " + result.matchedWords + "/" + result.totalWords + " كلمة معروفة (" + percent + "%)" + missingNote;
    return {
      translation: result.translation,
      corrections: [],
      meta: { offline: true, source: sourceCode || "auto", target: targetCode || "ar", status, matchedWords: result.matchedWords, totalWords: result.totalWords, unresolved: result.unresolved, dialect: codeNames[targetCode] || codeNames[sourceCode] || "العربية" }
    };
  }

  window.SEIF_DIALECT_ENGINE = {
    translate,
    normalize,
    getWordCount: () => prepared.length,
    getDialects: () => Object.keys(codeNames).map(code => ({ code, name: codeNames[code] }))
  };
